#!/usr/bin/env python3
"""sample-app-cli CLI - generated by clivane forge (deterministic, stdlib only).

Wraps the Python module `sample_app`: one subcommand per public function,
--json on every command, plus a stateful REPL when run with no args.
"""
import argparse
import importlib
import json
import os
import shlex
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
MODULE = importlib.import_module("sample_app")
SPECS = json.loads(r"""[
 {
  "args": [],
  "cmd": "count-notes",
  "doc": "Return how many notes exist.",
  "func": "count_notes"
 },
 {
  "args": [
   {
    "default": null,
    "flag": "--title",
    "name": "title",
    "required": true,
    "type": "str"
   },
   {
    "default": "",
    "flag": "--body",
    "name": "body",
    "required": false,
    "type": "str"
   }
  ],
  "cmd": "create-note",
  "doc": "Create a note with a title and an optional body; returns the note.",
  "func": "create_note"
 },
 {
  "args": [
   {
    "default": null,
    "flag": "--note-id",
    "name": "note_id",
    "required": true,
    "type": "int"
   }
  ],
  "cmd": "delete-note",
  "doc": "Delete a note by id; returns True when a note was removed.",
  "func": "delete_note"
 },
 {
  "args": [],
  "cmd": "list-notes",
  "doc": "List all notes, in creation order.",
  "func": "list_notes"
 },
 {
  "args": [
   {
    "default": null,
    "flag": "--query",
    "name": "query",
    "required": true,
    "type": "str"
   }
  ],
  "cmd": "search-notes",
  "doc": "Find notes whose title or body contains the query (case-insensitive).",
  "func": "search_notes"
 }
]""")


def coerce(value, type_name):
    if value is None:
        return None
    if type_name == "int":
        return int(value)
    if type_name == "float":
        return float(value)
    if type_name == "bool":
        return str(value).lower() in ("1", "true", "yes", "on")
    if type_name in ("list", "dict"):
        return json.loads(value)
    return value


def build_parser():
    parser = argparse.ArgumentParser(prog="sample-app-cli", description="Agent CLI for sample_app")
    sub = parser.add_subparsers(dest="command")
    for spec in SPECS:
        p = sub.add_parser(spec["cmd"], help=spec["doc"])
        for arg in spec["args"]:
            p.add_argument(arg["flag"], required=arg["required"],
                           default=arg["default"], help=arg["type"])
        p.add_argument("--json", action="store_true", help="structured JSON output")
    return parser


def dispatch(argv):
    parser = build_parser()
    ns = parser.parse_args(argv)
    if not ns.command:
        parser.print_help()
        return 2
    spec = next(s for s in SPECS if s["cmd"] == ns.command)
    kwargs = {}
    for arg in spec["args"]:
        kwargs[arg["name"]] = coerce(getattr(ns, arg["name"]), arg["type"])
    result = getattr(MODULE, spec["func"])(**kwargs)
    if ns.json:
        print(json.dumps({"command": spec["cmd"], "result": result},
                         indent=2, sort_keys=True, default=str))
    elif result is not None:
        if isinstance(result, (dict, list)):
            print(json.dumps(result, indent=2, sort_keys=True, default=str))
        else:
            print(result)
    return 0


def repl():
    print("sample-app-cli REPL - type a command, 'help', or 'exit'")
    while True:
        try:
            line = input("sample-app-cli> ").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            return 0
        if not line:
            continue
        if line in ("exit", "quit"):
            return 0
        if line == "help":
            build_parser().print_help()
            continue
        try:
            dispatch(shlex.split(line))
        except SystemExit as exc:
            if exc.code not in (0, None):
                print("error: exit %s" % exc.code)
        except Exception as exc:  # keep the session alive
            print("error: %s" % exc)


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if not argv:
        return repl()
    try:
        return dispatch(argv)
    except Exception as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
